 return `<div class="modal-scrim" data-action="close-modal"><div class="modal-dialog" role="dialog" aria-modal="true" aria-label="${attr(title)}" ><div class="modal-top"><div><span class="eyebrow">FIELDOPS</span><h2>${esc(title)}</h2></div><button class="modal-close" data-action="close-modal" title="Close">${icon('close',20)}</button></div><form id="modal-form" data-form="${attr(form)}">${body}<div class="modal-actions"><button type="button" class="secondary-btn" data-action="close-modal">Cancel</button><button type="submit" class="primary">${esc(button)} ${icon('arrow',16)}</button></div></form></div></div>`;
