function printMarkup(){const b=state.current;if(!b)return '';let media=b.media;return `<section class="print-report"><h1>WALLPANELS / FIELDOPS</h1><h2>${esc(b.project.title)}</h2><p>${esc(b.project.address)} | ${esc(b.project.status)} | ${esc(new Date().toLocaleString())}</p>${b.stages.map(s=>`<div class="print-stage"><h3>${esc(s.title)} — ${s.completion.done?'COMPLETE':'INCOMPLETE'}</h3><p>${esc(s.guide||'')}</p><div class="print-gallery">${media.filter(m=>m.stage_id===s.id).map(m=>m.kind==='image'?`<figure><img src="${attr(m.url||'')}"/><figcaption>${esc(m.category_key)} · ${esc(m.file_name)}</figcaption></figure>`:`<p>Video evidence: ${esc(m.file_name)}</p>`).join('')}</div><ul>${b.checks.filter(x=>x.stage_id===s.id).map(c=>`<li>${c.result_status==='done'?'✓':'○'} ${esc(c.label)}</li>`).join('')}</ul></div>`).join('')}<h3>Issues</h3>${b.issues.map(i=>`<p>${esc(i.title)} — ${esc(i.status)}: ${esc(i.description)} | ${esc(i.resolution||'')}</p>`).join('')}<h3>Daily reports</h3>${b.days.map(d=>`<p>${esc(d.report_date)} — ${esc(d.status)}</p>`).join('')}</section>`;}
function viewer(){if(!M.viewer||!state.current)return '';const items=state.current.media.filter(x=>x.url),index=Math.max(0,items.findIndex(x=>x.id===M.viewer)),m=items[index];if(!m)return '';return `<div class="media-viewer" role="dialog" aria-modal="true" aria-label="Просмотр файла"><button class="viewer-close" data-action="close-viewer" aria-label="Закрыть">${icon('close',25)}</button>${m.kind==='video'?`<video src="${attr(m.url)}" controls playsinline autoplay></video>`:`<img src="${attr(m.url)}" alt="${attr(m.file_name)}"/>`}<div class="viewer-meta"><strong>${esc(m.file_name)}</strong><small>${esc(m.uploader?.first_name||'Сотрудник')} · ${esc(new Date(m.created_at).toLocaleString('ru-RU'))}</small></div>${items.length>1?`<button class="viewer-prev" data-action="viewer-step" data-step="-1" aria-label="Предыдущий">${icon('back',25)}</button><button class="viewer-next" data-action="viewer-step" data-step="1" aria-label="Следующий">${icon('chevron',25)}</button>`:''}</div>`;}
function toastMarkup(){return M.toast?`<div class="toast ${M.toast.error?'is-error':''}" ${M.toast.error?'role="alert"':'role="status" aria-live="polite"'}>${M.toast.busy?'<span class="toast-spinner" aria-hidden="true"></span>':icon(M.toast.error?'alert':'checkCircle',18)} ${esc(M.toast.text)}</div>`:'';}
