function render(){const pages={home,projects:projectsPage,'project-loading':projectLoadingPage,project:projectPage,stage:stagePageV2,day:dayPage,issues:issuesPage,people:teamPage,profile:profilePage};let c;try{c=pages[M.page]?.()||home();}catch(e){console.error(e);c=empty('Display error','Try reopening this screen.','alert');}
 $('#app').innerHTML=`<div class="app-shell">${header()}<main class="main-area" id="main-content">${c}</main>${bottomNav()}<div id="modal-host">${modal()}</div><div id="viewer-host">${viewer()}</div><div id="toast-host">${toastMarkup()}</div></div><div id="print-area">${state.current?printMarkup():''}</div>`;
 localizeRoot($('#app'));
 focusModal();
 const search=$('#search-projects');if(search){search.addEventListener('input',e=>{M.search=e.target.value;const list=$('.project-grid');if(list){const filtered=state.projects.filter(p=>matchesProjectFilter(p,M.filter)&&`${p.title} ${p.address}`.toLowerCase().includes(M.search.toLowerCase()));list.innerHTML=filtered.map(projectCard).join('')||empty('No matching projects','Try another search term.','search');localizeRoot(list);}});}
}
