let toastTimer=null;
function toast(text,error=false){M.toast={text:ruText(text),error,busy:false};syncToast();clearTimeout(toastTimer);toastTimer=setTimeout(()=>{M.toast=null;syncToast();},3200);}
function busy(text='Saving...'){M.toast={text:ruText(text),error:false,busy:true};syncToast();}
async function refreshProjects(){if(M.preview)return;state.projects=(await request('/projects')).projects.filter(p=>p.status!=='archived');}
async function refreshCurrent(){if(!state.current)return; if(M.preview){recomputeDemo();return;}
 const id=state.current.project.id;state.current=await request(`/projects/${id}?fresh=1`);projectCache.set(id,{at:Date.now(),data:state.current});}
function recomputeLocal(){const b=state.current;if(!b)return;for(const s of b.stages){const media=b.media.filter(m=>m.stage_id===s.id),checks=b.checks.filter(c=>c.stage_id===s.id);s.completion={missingMedia:s.media_requirements.filter(r=>r.required&&!media.some(m=>m.category_key===r.key&&m.kind===r.kind)&&!(!['before','installed'].includes(s.stage_key)&&r.key!=='flags'&&b.exceptions.some(e=>e.stage_id===s.id&&e.category_key===r.key&&e.status==='approved'))).map(r=>r.label),missingChecks:checks.filter(c=>c.required&&c.result_status!=='done').map(c=>c.label)};s.completion.done=!s.completion.missingMedia.length&&!s.completion.missingChecks.length;if(!s.completion.done)s.completed=null;}}
const recomputeDemo=recomputeLocal;
function syncStageProgress(){const s=selectedStage();if(!s)return;const status=$('.stage-status.detailed');if(status){status.innerHTML=stageStatusMarkup(s);localizeRoot(status);}const checks=state.current.checks.filter(c=>c.stage_id===s.id),count=$('#stage-check-count');if(count)count.textContent=`${checks.filter(c=>c.result_status==='done').length}/${checks.length}`;const complete=$('.complete-stage');if(complete)complete.disabled=!s.completion.done||pendingCheckSaves>0;}
async function fetchProject(id,{fresh=false}={}){const cached=projectCache.get(id);if(!fresh&&cached&&Date.now()-cached.at<PROJECT_CACHE_MS)return cached.data;if(!fresh&&projectRequests.has(id))return projectRequests.get(id);const pending=request(`/projects/${id}${fresh?'?fresh=1':''}`).then(data=>{projectCache.set(id,{at:Date.now(),data});return data;}).finally(()=>projectRequests.delete(id));projectRequests.set(id,pending);return pending;}
function resetScroll(){window.scrollTo({top:0,left:0,behavior:'auto'});}
async function openProject(id){const ticket=++openProjectSequence,summary=state.projects.find(p=>p.id===id);try{const cached=projectCache.get(id);if(cached&&Date.now()-cached.at<PROJECT_CACHE_MS){state.current=cached.data;M.loadingProject=null;M.page='project';resetScroll();render();return;}M.loadingProject=summary||null;M.page='project-loading';resetScroll();render();state.current=M.preview?(id==='demo-project'?M.demoBundle:{...demoProject(),project:summary||state.projects[0]}):await fetchProject(id);if(ticket!==openProjectSequence)return;M.loadingProject=null;M.page='project';resetScroll();render();}catch(e){if(ticket!==openProjectSequence)return;M.loadingProject=null;M.page='projects';render();toast(e.message,true);}}
function scheduleProjectPrefetch(){if(M.preview||prefetchTimer||!state.projects.length)return;const run=async()=>{prefetchTimer=null;if(document.visibilityState==='hidden')return;await Promise.allSettled(state.projects.slice(0,3).map(p=>fetchProject(p.id)));};prefetchTimer=globalThis.requestIdleCallback?globalThis.requestIdleCallback(()=>void run(),{timeout:500}):setTimeout(()=>void run(),80);}
function page(page){openProjectSequence++;if(page==='day'&&!state.current){if(state.projects.length){void openProject(state.projects[0].id).then(()=>{M.page='day';render();});return;}page='projects';}M.page=page;resetScroll();render();if(page==='home'||page==='projects')scheduleProjectPrefetch();}
function fakeId(){return `demo-${Math.random().toString(36).slice(2)}`;}
async function mutate(cb,message='Saved'){try{busy();await cb();await refreshCurrent();await refreshProjects();render();toast(message);}catch(e){toast(e.message,true);}}
async function doForm(form,values){const b=state.current;switch(form){
 case 'custom-category':{const body={label:values.label,kind:values.kind,required:values.required==='true'};if(M.preview)selectedStage().media_requirements.push({...body,key:fakeId().replaceAll('-','_')});else await request(`/stages/${M.stage}/categories`,{method:'POST',data:body});M.modal=null;await refreshCurrent();toast('Photo requirement added');break;}
 case 'create':{if(M.preview){const p={...demoProject().project,id:fakeId(),code:`WP-DEMO-${state.projects.length+1}`,title:values.title,address:values.address,client_name:values.client_name||'',project_type:values.type,scheduled_for:values.scheduled_for||null,notes:values.notes||''};state.projects.unshift(p);}else await request('/projects',{method:'POST',data:values});await refreshProjects();M.modal=null;page('projects');toast('Project created');break;}
 case 'person':{if(M.preview)M.people.push({...values,id:fakeId()});else{const r=await request('/users',{method:'POST',data:values});M.lastInvite=r.invitation?.invite_url||null;}M.modal=null;await loadPeople();toast(M.lastInvite?'Персональная ссылка создана':'Сотрудник уже добавлен');break;}
 case 'assign':{if(!values.user_id)throw new Error('Add an installer to the team first.');if(M.preview){const person=M.people.find(x=>x.id===values.user_id);b.people.push(person);}else await request(`/projects/${b.project.id}/assign`,{method:'POST',data:values});M.modal=null;await refreshCurrent();toast('Installer assigned');break;}
 case 'edit-project':{await request(`/projects/${b.project.id}`,{method:'PATCH',data:values});M.modal=null;await refreshCurrent();await refreshProjects();toast('Проект обновлён');break;}
 case 'comment':{const comment=M.preview?{id:fakeId(),project_id:b.project.id,stage_id:M.stage,author_id:state.me.id,body:values.body,created_at:new Date().toISOString(),author:state.me,can_edit:true}:(await request(`/stages/${M.stage}/comments`,{method:'POST',data:values})).comment;b.comments||=[];b.comments.push(comment);M.modal=null;syncOverlay();syncComments();toast('Комментарий добавлен');return;}
 case 'edit-comment':{const result=M.preview?{...(b.comments||[]).find(x=>x.id===M.comment),body:values.body,updated_at:new Date().toISOString()}:(await request(`/comments/${M.comment}`,{method:'PATCH',data:values})).comment;const index=(b.comments||[]).findIndex(x=>x.id===M.comment);if(index>=0)b.comments[index]=result;M.modal=null;M.comment=null;syncOverlay();syncComments();toast('Комментарий обновлён');return;}
 case 'issue':{if(M.preview)b.issues.unshift({...values,id:fakeId(),status:'open',project_id:b.project.id,created_at:new Date().toISOString()});else await request(`/projects/${b.project.id}/issues`,{method:'POST',data:values});M.modal=null;await refreshCurrent();toast('Issue reported to PM');break;}
 case 'confirmation':{if(values.outcome==='refused'&&!values.notes?.trim())throw new Error('Please explain the refusal.');if(M.preview)b.confirmation={...values};else await request(`/projects/${b.project.id}/confirmation`,{method:'POST',data:values});M.modal=null;await refreshCurrent();toast('Client confirmation recorded');break;}
 case 'exception':{const body={stage_id:M.stage,category_key:M.category,reason:values.reason};if(M.preview)b.exceptions.push({...body,id:fakeId(),status:'pending'});else await request(`/projects/${b.project.id}/exceptions`,{method:'POST',data:body});M.modal=null;await refreshCurrent();toast('PM exception requested');break;}
 case 'resolve':{if(M.preview){const i=b.issues.find(i=>i.id===M.issue);i.status='resolved';i.resolution=values.resolution;}else await request(`/issues/${M.issue}/resolve`,{method:'POST',data:values});M.modal=null;await refreshCurrent();toast('Issue resolved');break;}
 case 'project-review':{if(values.status==='needs_changes'&&!values.note.trim())throw new Error('Please explain the corrections.');if(M.preview){b.project.status=values.status;b.project.review_note=values.note||'';}else await request(`/projects/${b.project.id}/review`,{method:'POST',data:values});M.modal=null;await refreshCurrent();await refreshProjects();toast('Decision saved');break;}
 case 'day-review':{if(values.status==='changes'&&!values.note.trim())throw new Error('Please provide a reason.');if(M.preview){const d=b.days.find(d=>d.id===M.day);d.status=values.status;d.pm_note=values.note||'';}else await request(`/days/${M.day}/review`,{method:'POST',data:values});M.modal=null;await refreshCurrent();toast('Daily report reviewed');break;}
 }render();}
async function loadPeople(){if(M.preview){if(!M.people.length)M.people=[...DEMO_PEOPLE];return;}if(state.view==='pm'){const r=await request('/users');M.people=r.people;M.invitations=r.invitations||[];}}
function uploadQueueMarkup(){if(!M.uploads.length)return '';return `<div class="upload-queue upload-progress" aria-live="polite">${M.uploads.map((x,i)=>`<div class="upload-item ${x.failed?'failed':''}"><span>${icon(x.done?'checkCircle':x.failed?'alert':'upload',15)}</span><span class="upload-copy"><strong>${esc(x.name)}</strong><small>${esc(x.status)}</small><span class="upload-track"><i style="width:${Number(x.progress||0)}%"></i></span></span>${x.failed?`<button data-action="retry-upload" data-index="${i}">Повторить</button>`:''}</div>`).join('')}</div>`;}
function syncUploadQueue(){const host=$('#upload-queue-host');if(host)host.innerHTML=uploadQueueMarkup();}
const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));let uploadQueueRunning=false;
async function performUpload(item){
 item.failed=false;for(let attempt=1;attempt<=3;attempt++){item.attempt=attempt;item.status=attempt===1?'Загрузка…':`Повтор ${attempt}/3…`;syncUploadQueue();try{
  if(M.preview){await wait(35);item.media={id:fakeId(),project_id:item.context.projectId,stage_id:item.context.stageId||null,daily_report_id:item.context.dayId||null,issue_id:item.context.issueId||null,category_key:item.context.category,kind:uploadContentType(item.file).startsWith('video/')?'video':'image',file_name:item.file.name,url:URL.createObjectURL(item.file),uploaded_by:state.me.id,created_at:new Date().toISOString()};item.progress=100;}
  else item.media=await uploadMedia(item.context.projectId,{...item.context,file:item.file,onProgress:value=>{item.progress=value;syncUploadQueue();}});
  if(state.current?.project.id===item.context.projectId&&item.media&&!state.current.media.some(m=>m.id===item.media.id))state.current.media.unshift(item.media);
  item.done=true;item.status='Сохранено и проверено';item.progress=100;syncUploadQueue();return true;
 }catch(e){item.error=e.message;if(attempt<3&&e.retryable){item.status=`Сбой сети, повторяем…`;syncUploadQueue();await wait(350*2**(attempt-1));continue;}item.failed=true;item.status=`Ошибка: ${e.message}`;syncUploadQueue();return false;}}
}
async function runUploadQueue(){if(uploadQueueRunning)return;uploadQueueRunning=true;let saved=0,failed=0;
 const worker=async()=>{while(true){const item=M.uploads.find(x=>!x.done&&!x.failed&&!x.running);if(!item)return;item.running=true;const ok=await performUpload(item);item.running=false;if(ok)saved++;else failed++;}};
 await Promise.all([worker(),worker(),worker()]);uploadQueueRunning=false;
 const projectId=state.current?.project.id;if(projectId&&M.uploads.some(x=>x.done&&x.context.projectId===projectId)){recomputeLocal();projectCache.set(projectId,{at:Date.now(),data:state.current});render();}
 toast(failed?`Сохранено: ${saved}. Ошибок: ${failed}. Файлы оставлены для повтора.`:`Надёжно сохранено файлов: ${saved}`,failed>0);
 if(!failed)setTimeout(()=>{M.uploads=M.uploads.filter(x=>!x.done);syncUploadQueue();},3500);
 if(M.uploads.some(x=>!x.done&&!x.failed))void runUploadQueue();
}
async function uploadFiles(files,context){const b=state.current;if(!b||!files.length)return;const accepted=[];
 for(const file of files){const type=uploadContentType(file),kind=type.startsWith('video/')?'video':'image';let error='';if(!type)error='Неподдерживаемый формат';else if((kind==='image'&&file.size>15*1024*1024)||file.size>50*1024*1024)error='Превышен размер файла';
  if(context.stageId){const r=selectedStage()?.media_requirements.find(x=>x.key===context.category);if(r&&r.kind!==kind)error=`Нужен файл типа: ${r.kind==='video'?'видео':'фото'}`;}
  accepted.push({name:file.name,status:error?`Ошибка: ${error}`:'Ожидает',progress:0,done:false,failed:Boolean(error),file,context:{...context,projectId:b.project.id}});
 }
 M.uploads.push(...accepted);M.modal=null;syncOverlay();syncUploadQueue();void runUploadQueue();
}
function markCheckState(target,stateName){const row=target.closest('.check-line');row?.classList.remove('is-saving','is-saved');if(stateName)row?.classList.add(stateName);}
async function saveStageCheck(target){if(target.dataset.saving)return;const check=state.current?.checks.find(c=>c.id===target.dataset.checkId);if(!check)return;const done=target.checked,previous=check.result_status;target.dataset.saving='1';target.disabled=true;pendingCheckSaves++;markCheckState(target,'is-saving');check.result_status=done?'done':'pending';recomputeLocal();syncStageProgress();try{if(!M.preview)await request(`/checks/${check.id}`,{method:'POST',data:{done}});projectCache.set(state.current.project.id,{at:Date.now(),data:state.current});markCheckState(target,'is-saved');setTimeout(()=>markCheckState(target,''),650);}catch(error){check.result_status=previous;target.checked=previous==='done';recomputeLocal();syncStageProgress();markCheckState(target,'');toast(`Не удалось сохранить галочку: ${error.message}`,true);}finally{delete target.dataset.saving;target.disabled=false;pendingCheckSaves--;syncStageProgress();}}
async function saveDayCheck(target){if(target.dataset.saving)return;const day=state.current?.days.find(d=>d.id===M.day)||state.current?.days[0];if(!day)return;const key=target.dataset.dayCheck,done=target.checked,previous=Boolean(day.checks?.[key]);day.checks||={};day.checks[key]=done;target.dataset.saving='1';target.disabled=true;markCheckState(target,'is-saving');try{if(!M.preview)await request(`/days/${day.id}/check`,{method:'POST',data:{key,done}});projectCache.set(state.current.project.id,{at:Date.now(),data:state.current});markCheckState(target,'is-saved');setTimeout(()=>markCheckState(target,''),650);}catch(error){day.checks[key]=previous;target.checked=previous;markCheckState(target,'');toast(`Не удалось сохранить галочку: ${error.message}`,true);}finally{delete target.dataset.saving;target.disabled=false;}}
async function clickAction(el){const action=el.dataset.action;
 switch(action){
 case 'home':page('home');break;
 case 'profile':page('profile');break;
 case 'nav':{if(el.dataset.page==='people')await loadPeople();page(el.dataset.page);break;}
 case 'back':if(['stage','day','issues'].includes(M.page))page('project');else page('projects');break;
 case 'open-project':await openProject(el.dataset.id);break;
 case 'open-stage':M.stage=el.dataset.id;M.category=null;page('stage');break;
 case 'open-day':{M.day=state.current.days[0]?.id||null;page('day');break;}
 case 'open-issues':page('issues');break;
 case 'open-media':{const m=state.current?.media.find(x=>x.url);if(m){M.viewer=m.id;render();}else toast('Файлов пока нет',true);break;}
 case 'stats-filter':M.filter=el.dataset.filter;page('home');break;
 case 'filter':M.filter=el.dataset.filter;render();break;
 case 'modal':if(['assign','create','edit-project'].includes(el.dataset.modal))await loadPeople();if(el.dataset.modal==='day-review')M.day=M.day||state.current.days[0]?.id;M.modal=el.dataset.modal;syncOverlay();break;
 case 'open-comment':M.modal='comment';syncOverlay();break;
 case 'close-modal':M.modal=null;syncOverlay();break;
 case 'media-menu':M.category=el.dataset.category;M.modal='media-actions';syncOverlay();break;
 case 'pick-category':M.category=el.dataset.category;render();document.querySelector('.upload-panel')?.scrollIntoView({behavior:'smooth',block:'nearest'});break;
 case 'camera':case 'gallery':case 'documents':{
  const input=$('#'+(action==='camera'?'camera-file':action==='gallery'?'gallery-files':'document-files'));if(!input)return;
  const r=selectedStage()?.media_requirements.find(c=>c.key===M.category);input.accept=r?.kind==='video'?'video/*':'image/*';input.click();break;}
 case 'day-upload':$('#day-file')?.click();break;
 case 'new-day':await mutate(async()=>{if(M.preview){const date=new Date().toISOString().slice(0,10);let day=state.current.days.find(d=>d.report_date===date);if(!day){day={id:fakeId(),report_date:date,checks:{},status:'open'};state.current.days.unshift(day);}M.day=day.id;}else{const r=await request(`/projects/${state.current.project.id}/days`,{method:'POST',data:{}});M.day=r.day.id;}},'Daily report opened');break;
 case 'choose-day':M.day=el.dataset.id;render();break;
 case 'submit-day':await mutate(async()=>{const d=state.current.days.find(d=>d.id===M.day);if(M.preview){if(!state.current.media.some(m=>m.daily_report_id===d.id)||!state.current.dayChecks.every(c=>d.checks?.[c.key]))throw new Error('Complete daily checks and photo first');d.status='submitted';}else await request(`/days/${d.id}/submit`,{method:'POST',data:{}});},'Daily report submitted');break;
 case 'request-na':M.category=el.dataset.category;M.modal='exception';syncOverlay();break;
 case 'review-exception':await mutate(async()=>{if(M.preview){state.current.exceptions.find(x=>x.id===el.dataset.id).status=el.dataset.result;}else await request(`/exceptions/${el.dataset.id}/review`,{method:'POST',data:{status:el.dataset.result}});},'Exception reviewed');break;
 case 'issue-upload':M.issue=el.dataset.id;$('#issue-file')?.click();break;
 case 'resolve-issue':M.issue=el.dataset.id;M.modal='resolve';render();break;
 case 'submit-project':await mutate(async()=>{if(M.preview){recomputeDemo();const b=state.current;if(b.stages.some(s=>!s.completion.done)||!b.days.length||b.days.some(d=>d.status!=='approved')||b.issues.some(i=>i.status==='open')||!b.confirmation)throw new Error('Complete all stages, approved daily reports, issues and client confirmation first.');b.project.status='in_review';}else await request(`/projects/${state.current.project.id}/submit`,{method:'POST',data:{}});},'Sent to Project Manager');break;
 case 'complete-stage':await mutate(async()=>{await request(`/stages/${M.stage}/complete`,{method:'POST',data:{}});},'Этап завершён');break;
 case 'remove-member':await mutate(async()=>{await request(`/projects/${state.current.project.id}/members/${el.dataset.id}`,{method:'DELETE'});},'Сотрудник снят с проекта');break;
 case 'archive-project':{const project=state.current?.project;if(!project||!confirm(`Точно удалить «${project.title}» из рабочего списка?\n\nПроект исчезнет из списка, но история сохранится в архиве.`))break;try{busy('Удаляем проект из списка…');if(!M.preview)await request(`/projects/${project.id}/archive`,{method:'POST',data:{}});state.projects=state.projects.filter(p=>p.id!==project.id);projectCache.delete(project.id);state.current=null;M.page='projects';render();toast('Проект удалён из рабочего списка');}catch(error){toast(error.message,true);}break;}
 case 'edit-comment':M.comment=el.dataset.id;M.modal='edit-comment';syncOverlay();break;
 case 'delete-comment':if(confirm('Удалить комментарий? История останется в аудите.')){if(!M.preview)await request(`/comments/${el.dataset.id}`,{method:'DELETE'});state.current.comments=(state.current.comments||[]).filter(x=>x.id!==el.dataset.id);syncComments();toast('Комментарий удалён');}break;
 case 'delete-media':if(confirm('Удалить ошибочно загруженный файл? История загрузки и удаления сохранится.'))await mutate(async()=>{if(M.preview)state.current.media=state.current.media.filter(x=>x.id!==el.dataset.id);else await request(`/media/${el.dataset.id}`,{method:'DELETE'});},'Файл удалён. Можно загрузить замену.');break;
 case 'view-media':M.viewer=el.dataset.id;syncViewer();break;
 case 'close-viewer':M.viewer=null;syncViewer();break;
 case 'viewer-step':{const items=state.current.media.filter(x=>x.url),i=items.findIndex(x=>x.id===M.viewer),n=(i+Number(el.dataset.step)+items.length)%items.length;M.viewer=items[n]?.id;syncViewer();break;}
 case 'copy-invite':await navigator.clipboard.writeText(M.lastInvite);toast('Ссылка скопирована');break;
 case 'retry-upload':{const item=M.uploads[Number(el.dataset.index)];if(item?.file){item.failed=false;item.done=false;item.running=false;item.progress=0;item.status='Ожидает';syncUploadQueue();void runUploadQueue();}break;}
 case 'print':window.print();break;
 case 'view':state.view=el.dataset.view;await loadPeople().catch(()=>{});page('home');toast(`Viewing as ${state.view==='pm'?'Project Manager':'Installer'}`);break;
 case 'logout':sessionStorage.removeItem('fieldops_token');location.reload();break;
 }}
window.addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(!btn)return;if(btn.classList.contains('modal-scrim')&&e.target.closest('.modal-dialog'))return;e.preventDefault();void clickAction(btn).catch(e=>toast(e.message,true));});
window.addEventListener('pointerdown',e=>{const card=e.target.closest('[data-action="open-project"]');if(card&&!M.preview)void fetchProject(card.dataset.id).catch(()=>{});},{passive:true});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&M.viewer){M.viewer=null;syncViewer();}else if(e.key==='Escape'&&M.modal){M.modal=null;syncOverlay();}});
window.addEventListener('submit',e=>{if(e.target.id!=='modal-form')return;e.preventDefault();const form=e.target;const values=Object.fromEntries(new FormData(form).entries());
 const button=form.querySelector('[type=submit]');button.disabled=true;button.textContent='Сохранение…';
 void doForm(form.dataset.form,values).catch(e=>{toast(e.message,true);button.disabled=false;button.textContent='Повторить';});});
window.addEventListener('change',e=>{
 const target=e.target;
 if(target.id==='report-project-select'){const id=target.value;void fetchProject(id).then(bundle=>{state.current=bundle;M.day=bundle.days[0]?.id||null;M.page='day';render();}).catch(error=>toast(error.message,true));return;}
 if(target.id==='stage-cat'){M.category=target.value;return;}
 if(target.dataset.checkId){void saveStageCheck(target);return;}
 if(target.dataset.dayCheck){void saveDayCheck(target);return;}
 if(['camera-file','gallery-files','document-files'].includes(target.id)){const r=selectedStage()?.media_requirements.find(x=>x.key===M.category);if(!r)return;M.modal=null;void uploadFiles([...target.files],{stageId:M.stage,category:r.key});target.value='';return;}
 if(target.id==='day-file'){const d=state.current.days.find(d=>d.id===M.day);if(!d){toast('Create a daily report first',true);return;}void uploadFiles([...target.files],{dayId:d.id,category:'daily_site'});target.value='';return;}
 if(target.id==='issue-file'){void uploadFiles([...target.files],{issueId:M.issue,category:'issue_evidence'});target.value='';return;}
});
async function init(){try{
 if(M.preview){demoData();M.people=[...DEMO_PEOPLE];render();return;}
 if(state.token){const [me,projects]=await Promise.all([request('/me'),request('/projects')]);state.me=me.user;state.projects=projects.projects.filter(p=>p.status!=='archived');state.view=['installer','foreman'].includes(state.me.role)?'installer':'pm';}
 else{await loginTelegram();await refreshProjects();}
 render();if(state.projects[0])void fetchProject(state.projects[0].id).catch(()=>{});scheduleProjectPrefetch();
 }catch(e){$('#app').innerHTML=`<div class="auth-page"><span class="brand-icon large-logo">W.</span><h1>WallPanels FieldOps</h1><p>${esc(ruText(e.message))}</p><p class="auth-note">Только для авторизованных сотрудников.<br>Откройте Telegram-бота и нажмите <strong>Open FieldOps</strong>.</p></div>`;localizeRoot($('#app'));}}
void init();
